    if (wins && CFArrayGetCount(wins)>0) {
        for (CFIndex i=0;i<CFArrayGetCount(wins);i++) dumpWin((AXUIElementRef)CFArrayGetValueAtIndex(wins,i), "kAXWindows");
        CFRelease(wins);
    } else {
        if (wins) CFRelease(wins);
        // try main/focused
        CFTypeRef m=NULL, f=NULL;
        if (AXUIElementCopyAttributeValue(app, kAXMainWindowAttribute, &m)==kAXErrorSuccess && m) {
            dumpWin((AXUIElementRef)m, "AXMainWindow");
            CFRelease(m);
        } else NSLog(@"no AXMainWindow");
        if (AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute, &f)==kAXErrorSuccess && f) {
            dumpWin((AXUIElementRef)f, "AXFocusedWindow");
            CFRelease(f);
        } else NSLog(@"no AXFocusedWindow");
        // also try to enumerate via CGWindowList and then resolve via AX
        CFArrayRef cg = CGWindowListCopyWindowInfo(kCGWindowListOptionAll|kCGWindowListExcludeDesktopElements, kCGNullWindowID);
        for (CFIndex i=0;i<CFArrayGetCount(cg);i++) {
            CFDictionaryRef d=CFArrayGetValueAtIndex(cg,i);
            CFNumberRef pidN=CFDictionaryGetValue(d,kCGWindowOwnerPID);
            int p=0; if (pidN) CFNumberGetValue(pidN,kCFNumberIntType,&p);
            if (p!=pid) continue;
            CFNumberRef widN=CFDictionaryGetValue(d,kCGWindowNumber);
            int wid=0; if (widN) CFNumberGetValue(widN,kCFNumberIntType,&wid);
            CFDictionaryRef b=CFDictionaryGetValue(d,kCGWindowBounds);
            CGRect r; CGRectMakeWithDictionaryRepresentation(b,&r);
            NSLog(@"CG wid=%d frame %.0fx%.0f@%.0f,%.0f name=%@", wid, r.size.width, r.size.height, r.origin.x, r.origin.y, CFDictionaryGetValue(d,kCGWindowName));
        }
        CFRelease(cg);
    }
    CFRelease(app);
    return 0;
}
